function* countdown(n) {                        // coalgebra: unfold on demand
  for (let s = n; s > 0; s--) yield s;          // state lives in the frame
}

function factorial(n) {
  let acc = 1n;                                 // algebra: fold in the same pass
  for (const v of countdown(n)) acc *= BigInt(v);   // no array is built
  return acc;
}
